tc qdisc show dev enP2p1s0f1np1 | grep clsact >/dev/null || tc qdisc add dev enP2p1s0f1np1 clsact
tc filter replace dev enP2p1s0f1np1 ingress protocol 0x88b5 pref 49155 handle 49155 flower skip_sw src_mac 4c:bb:47:80:f1:47 dst_mac 4c:bb:47:80:ab:b4 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:b2:10 pipe action mirred egress redirect dev enP2p1s0f0np0
tc -s filter show dev enP2p1s0f1np1 ingress pref 49155 | grep -F -- 'eth_type 88b5' >/dev/null || { echo 'rule pref 49155 on enP2p1s0f1np1 does not match the generated selector/action: eth_type 88b5'; exit 3; }
