tc -s filter show dev enP2p1s0f0np0 ingress pref 49161 | grep -F -- 'dst_mac 4c:bb:47:80:ab:b3' >/dev/null || { echo 'rule pref 49161 on enP2p1s0f0np0 does not match the generated selector/action: dst_mac 4c:bb:47:80:ab:b3'; exit 3; }
